create table public.shipments (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, carrier text, tracking_number text, status text not null default 'pending' check(status in ('pending','labelled','shipped','delivered','exception','returned')), shipped_at timestamptz, delivered_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id) on delete cascade);
